; Lost jet wait and reset of the play state
; $5640-$5682

; Main loop part for a lost jet. When the jet frame is $90 or more and tick = $4f, it runs on into reset_play_state.
jet_lost_wait
        lda SPRPTR
        cmp #$90
        bcc jet_lost_wait_done
        lda tick
        cmp #$4f
        bne jet_lost_wait_done
        nop                             ; NOP fill.
; Clears the play state $17-$64 but keeps lives, sets $3c-$43 to $ff, clears $98-$b0, silences the SID. The cold start also calls it.
reset_play_state
        jsr airfields_restore
        ldy lives
        ldx #$4e
        lda #$00
reset_play_clear_zp
        sta $16,x
        dex
        bne reset_play_clear_zp
        sty lives                       ; Puts back lives.
        lda #$ff
        ldx #$07
reset_play_fill_ff
        sta enemy_shot_row,x
        dex
        bpl reset_play_fill_ff
        ldx #$18
        lda #$00
reset_play_clear_98
        sta pitch_active,x
        dex
        bpl reset_play_clear_98
        lda #$0a
        sta launch_delay
        lda #$02
        sta gauge_colour                ; $2e = 2: the colour of the GAS gauge ($4ea0).
        jsr sid_clear                   ; Clears the SID registers.
        lda #$00
        sta crash_stage
        jsr jet_frames_reset
jet_lost_wait_done
        rts
